// Generated by scripts/generate_scaling_osd.py.
// OSD reference: contest Lab3 hdmi_mixer.v; existing chars reused from osd_char_lib.v.
// Extended to frame metadata, 24px Chinese, 2-bit synchronous logo ROM and crosshair.
`default_nettype none
module scaling_osd(
    input wire I_clk,I_rst_n,I_vs,I_hs,I_de,
    input wire [23:0] I_rgb,
    input wire [10:0] I_cx,I_cross_x,
    input wire [9:0] I_cy,I_cross_y,
    input wire [1:0] I_zoom,I_mode,I_direction,
    input wire [2:0] I_status,
    input wire I_video_ok,
    output reg O_vs,O_hs,O_de,
    output reg [23:0] O_rgb
);
    reg [10:0] x;
    reg [9:0] y;
    reg vs_last;
    wire [10:0] dx=x>=I_cross_x ? x-I_cross_x:I_cross_x-x;
    wire [9:0] dy=y>=I_cross_y ? y-I_cross_y:I_cross_y-y;
    wire yellow=(dx>=3 && dx<=12 && dy<=1)||(dy>=3 && dy<=12 && dx<=1);
    wire outline=(dx>=2 && dx<=13 && dy<=2)||(dy>=2 && dy<=13 && dx<=2);
    reg [6:0] glyph;
    reg [4:0] gx,gy;
    reg text_on,brand;
    reg [5:0] column;
    wire [2:0] status=I_video_ok?I_status:3'd4;
    wire [23:0] glyph_bits;
    wire [1:0] logo_bits;
    wire logo_on=x>=1032 && x<1128 && y>=641 && y<703;
    wire [12:0] logo_addr=(y-641)*13'd96+(x-1032);
    wire [10:0] glyph_addr=glyph*11'd24+gy;
    scaling_glyph_rom u_font(I_clk,glyph_addr,glyph_bits);
    scaling_logo_rom u_logo(I_clk,logo_addr,logo_bits);
    always @* begin
        glyph=0; gx=0; gy=0; column=0; text_on=0; brand=0;
        if(x>=16 && x<1000 && ((y>=636 && y<660)||(y>=680 && y<704))) begin
            text_on=1; column=(x-16)/24; gx=(x-16)%24;
            if(y<660) begin
                gy=y-636;
                case(column)
                0:glyph=44;
                1:glyph=36;
                2:glyph=59;
                7:glyph=31;
                8:glyph=43;
                9:glyph=59;
                10:glyph=1;
                15:glyph=3;
                20:glyph=2;
                22:glyph=20;
                23:glyph=47;
                24:glyph=59;
                26:glyph=20;
                3: case(I_mode) 0:glyph=26;1:glyph=56;2:glyph=45;3:glyph=19; endcase
                4: case(I_mode) 0:glyph=30;1:glyph=53;2:glyph=35;3:glyph=21; endcase
                5: glyph=(I_mode==3)?25:0;
                11:glyph=4+I_cx/1000;
                12:glyph=4+(I_cx/100)%10;
                13:glyph=4+(I_cx/10)%10;
                14:glyph=4+I_cx%10;
                16:glyph=4+I_cy/1000;
                17:glyph=4+(I_cy/100)%10;
                18:glyph=4+(I_cy/10)%10;
                19:glyph=4+I_cy%10;
                25:glyph=4+(1<<I_zoom);
                endcase
            end else begin
                gy=y-680;
                case(column)
                0:glyph=15;
                1:glyph=14;
                2:glyph=16;
                3:glyph=7;
                4:glyph=41;
                5:glyph=28;
                6:glyph=59;
                9:glyph=46;
                10:glyph=38;
                11:glyph=59;
                7:case(I_direction) 0:glyph=18;1:glyph=27;2:glyph=34;3:glyph=17;endcase
                12:case(status) 0:glyph=37;1:glyph=50;2:glyph=23;3:glyph=40;4:glyph=54;default:glyph=0;endcase
                13:case(status) 0:glyph=29;1:glyph=24;2:glyph=56;3:glyph=57;4:glyph=58;default:glyph=0;endcase
                14:case(status) 2:glyph=48;3:glyph=22;4:glyph=42;default:glyph=0;endcase
                15:case(status) 3:glyph=51;4:glyph=33;default:glyph=0;endcase
                16:glyph=(status==4)?52:0;
                endcase
            end
        end else if(x>=1144 && x<1240 && y>=660 && y<684) begin
            text_on=1; brand=1; gx=(x-1144)%24; gy=y-660;
            case((x-1144)/24)
            0: glyph=32;
            1: glyph=55;
            2: glyph=49;
            3: glyph=39;
            endcase
        end
    end
    reg vs0,hs0,de0,text0,brand0,logo0;
    reg [4:0] gx0;
    reg [23:0] background0;
    always @(posedge I_clk or negedge I_rst_n) begin
        if(!I_rst_n) begin
            x<=0;y<=0;vs_last<=0;vs0<=0;hs0<=0;de0<=0;text0<=0;brand0<=0;logo0<=0;gx0<=0;
            background0<=0;O_vs<=0;O_hs<=0;O_de<=0;O_rgb<=0;
        end else begin
            vs_last<=I_vs;
            if(I_vs&&!vs_last) begin x<=0;y<=0;end
            else if(I_de) begin if(x==1279) begin x<=0;y<=y+1'b1;end else x<=x+1'b1;end
            vs0<=I_vs;hs0<=I_hs;de0<=I_de;text0<=text_on;brand0<=brand;logo0<=logo_on;gx0<=gx;
            if(y>=624) background0<=(x>=1024 && x<1264 && y>=632 && y<712)?24'hffffff:24'h102030;
            else if(yellow) background0<=24'hffff00;
            else if(outline || !I_video_ok) background0<=0;
            else background0<=I_rgb;
            O_vs<=vs0;O_hs<=hs0;O_de<=de0;
            if(!de0) O_rgb<=0;
            else if(text0 && glyph_bits[23-gx0]) O_rgb<=brand0?24'h1c2c4e:24'hffffff;
            else if(logo0 && logo_bits!=0) O_rgb<=logo_bits==2?24'hed1b23:24'h1c2c4e;
            else O_rgb<=background0;
        end
    end
endmodule
`default_nettype wire
